import {sequenceCurveType} from './sequence-curves.js';import {editCurveKeys} from './curve-tools.js';import {timelineFPS} from './timeline-rate.js';import {validGameplayAsset} from './gameplay-assets.js';
export function editSequenceCurves(data,params){const ids=params.tracks??[params.track];if(!Array.isArray(ids)||!ids.length||new Set(ids).size!==ids.length||ids.some(id=>typeof id!=='string'))throw Error('서로 다른 곡선 트랙 ID를 선택하세요.');const selected=new Set(ids),next={...data,tracks:data.tracks.map(t=>selected.has(t.id)?structuredClone(t):t)},rows=[];for(const id of ids){const track=next.tracks.find(t=>t.id===id);if(!track||track.quaternionInterpolation||!sequenceCurveType(track))throw Error('연속 값 트랙을 선택하세요.');if(params.operation==='eulerFilter'&&track.type!=='rotation')throw Error('Euler 필터는 회전 트랙에 적용하세요.');Object.assign(track,editCurveKeys(track,{...params,fps:params.fps??timelineFPS(data)}));rows.push({id,keys:track.keys.length});}if(!validGameplayAsset('sequenceasset',next))throw Error('곡선의 시간·값·전체 키 예산을 확인하세요.');for(const id of ids)Object.assign(data.tracks.find(t=>t.id===id),next.tracks.find(t=>t.id===id));return {keys:rows.reduce((n,r)=>n+r.keys,0),tracks:rows};}
export const sequenceMultiCurveContract={editing:'Choose visible sequence curves, Ctrl/Command key selection across owners, marquee and Ctrl+A, shared time/value drag, interpolation/weights/delete and curve tools in one Undo. One active channel is applied to each selected track; scalar tracks use channel0.',automation:{method:'sequence.curve.tool',track:'existing single track ID',tracks:'optional unique ID array for atomic batch, same tool parameters; explicit tracks takes precedence'},clipboard:'hb.curve.group v1 preserves relative track times, IDs then unique same-name/type destinations; all validation before mutation. Existing single curve clipboard retained.',view:'Visible track IDs are per-document view state, never persisted as sequence bindings or keys.',remaining:['Per-key simultaneous channel-axis selections']};
